text:
/* Used for Breeze titlebar-button buttons */
--toolbox-background-color: -moz-headerbar;
--toolbox-text-color: -moz-headerbartext;
--toolbox-background-color-inactive: -moz-headerbarinactive;
--toolbox-text-color-inactive: -moz-headerbarinactivetext;

&[lwtheme] {
  --toolbox-background-color: var(--lwt-frame);
  --toolbox-background-color-inactive: var(--lwt-frame-inactive, var(--lwt-frame));
  --toolbox-text-color: var(--lwt-text-color, currentColor);
  --toolbox-text-color-inactive: var(--lwt-text-color, currentColor);
}
